with lines as (select id, service, level, latency_ms, status_code, k, value from app_logs lateral view outer explode(context) x as k, value) select id, service, level, latency_ms, status_code, k, value, count(status_code) over w_hist service_count_status_code, round(latency_ms / sum(latency_ms) over (partition by k), 4) latency_ms_share, sum(latency_ms) over (partition by k, level) k_sum_latency_ms, round(status_code / sum(status_code) over (partition by k), 4) status_code_share, percent_rank() over (partition by level order by status_code) status_code_percent_rank from lines window w_hist as (partition by service)
